import { execFile } from 'node:child_process';
import { lstat, realpath } from 'node:fs/promises';
import { homedir } from 'node:os';
import { isAbsolute, join } from 'node:path';
import { fail, SigningError } from './pki.js';
export const DEFAULT_SEQUENCE_DIRECTORY = join(homedir(), '.local', 'state', 'bambu-printer-mcp', 'signing');
/** Directory containing the explicitly initialized durable shared POSIX counter.
 * This coordinates processes using THIS directory. It makes no claim about
 * sequences generated by Studio, Home Assistant, other hosts or deleted state. */
export class SequenceStore {
    constructor(directory = DEFAULT_SEQUENCE_DIRECTORY) {
        this.directory = directory;
    }
    async check() {
        try {
            if (!isAbsolute(this.directory) || await realpath(this.directory) !== this.directory)
                return fail('SIGNING_SEQUENCE_UNAVAILABLE');
            for (const [path, isDirectory] of [[this.directory, true], [join(this.directory, 'counter-helper'), false], [join(this.directory, 'counter'), false]]) {
                const st = await lstat(path);
                if (st.isSymbolicLink() || st.uid !== process.getuid?.() || (st.mode & 0o077) || (isDirectory ? !st.isDirectory() : !st.isFile()))
                    return fail('SIGNING_SEQUENCE_UNAVAILABLE');
            }
        }
        catch {
            return fail('SIGNING_SEQUENCE_UNAVAILABLE');
        }
    }
    async next() {
        await this.check();
        return new Promise((resolve, reject) => {
            execFile(join(this.directory, 'counter-helper'), ['next', this.directory], { timeout: 5000, killSignal: 'SIGKILL', maxBuffer: 1024, encoding: 'utf8' }, (error, stdout) => {
                const value = stdout.trim();
                if (error || !/^\d{5,10}$/.test(value) || Number(value) > 2147483647 || Number(value) <= 20000)
                    reject(new SigningError('SIGNING_SEQUENCE_UNAVAILABLE'));
                else
                    resolve(value);
            });
        });
    }
}
